  version "0.28.0"
  sha256 arm:   "0ea40c9666b5b94f6f93dbda49f968e814216b0e98c8cf14686e99a198b7c2b2",
         intel: "c665f4730771c07dce6bf9b528d32681557af15cedbdf2633b5fbf6302a5f66b"

  url "https://replynav.s3.eu-west-1.amazonaws.com/releases/stable/#{version}/ReplyNav-osx-#{arch}.dmg"
  name "ReplyNav"
  desc "AI writing assistant for selected text"
  homepage "https://replynav.com/"

  livecheck do
    url "https://replynav.s3.eu-west-1.amazonaws.com/releases/stable/latest-macos.json"
    strategy :json do |json|
      json["version"]
    end
  end

  # The app updates itself from the release manifests.
  auto_updates true
  depends_on macos: :sonoma

  app "ReplyNav.app"

  zap trash: [
    "~/Library/Application Support/ReplyNav",
    "~/Library/Caches/com.replynav.app",
    "~/Library/Preferences/com.replynav.app.plist",
  ]
